/** CLI-owned; regenerated by setu generate module or setu generate … --module <name>. */
import type { IRouterApi, IServiceRegistry } from '@setu-ts/common';
import { registerAuditModule } from './audit/index.ts';
import { registerDiagnosticsModule } from './diagnostics/index.ts';
import { registerValuesModule } from './values/index.ts';

/** Registers the feature routes. */
export function registerModules(router: IRouterApi, services?: IServiceRegistry): void {
  registerAuditModule(router, services);
  registerDiagnosticsModule(router, services);
  registerValuesModule(router, services);
}
